INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43011, 'Isaiah 39:5', 'Isaiah', 39, 5, 'بیا اشعیا حزقیا پاچا ته وویل: «مطلق قادر څښتن داسې وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_5.mp3', '', 1761754199, 1761754199),
(43012, 'Isaiah 39:6', 'Isaiah', 39, 6, 'داسې وخت راتلونکی دی چې هرڅه چې ستا په ماڼۍ کې دي او هرڅه چې ستا نیکونو تر نن ورځې پورې ذخیره کړي دي، هغه به بابل ته یووړل شي. هېڅ شی به پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_6.mp3', '', 1761754199, 1761754199),
(43013, 'Isaiah 39:7', 'Isaiah', 39, 7, 'ستا د خپلې اولادې څخه به ځینې په اسارت یووړل شي او هغوی به خصیان شي چې د بابل د پاچا په ماڼۍ کې خدمت وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_7.mp3', '', 1761754199, 1761754199),
(43014, 'Isaiah 39:8', 'Isaiah', 39, 8, 'حزقیا پاچا فکر وکړ چې دا خبره دا معنی لري چې د هغه په ژوند کې به سوله او امن وي، نو هغه ځواب ورکړ: «هغه پیغام چې تا د څښتن له خوا ماته راکړ ښه پیغام دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah39_verse_8.mp3', '', 1761754199, 1761754199),
(43015, 'Judges 19:1', 'Judges', 19, 1, 'په هغې زمانه کې چې اسراییلو پاچا نه درلود، د لاوي د قبیلې یو کس چې د افرایم د غرنۍ سیمې په یو لېرې ځای کې اوسېده، د بیت لحم څخه چې د یهودا په سیمه کې ؤ، یوه وینځه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_1.mp3', '', 1761754199, 1761754199),
(43016, 'Judges 19:2', 'Judges', 19, 2, 'خو هغه وینځه یعنې د لاوي ښځه د لاوي څخه خفه شوه او بېرته د خپل پلار کور ته چې په بیت لحم کې ؤ، لاړه او څلور میاشتې هلته پاتې شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_2.mp3', '', 1761754199, 1761754199),
(43017, 'Judges 19:3', 'Judges', 19, 3, 'بیا د هغې مېړه پرېکړه وکړه چې د هغې پسې لاړ شي او هغه هڅوي چې بېرته راشي. نو خپل نوکر او دوه خره یې د ځان سره واخیستل. کله چې د خپل خسر کور ته ورسېده، ښځې یې هغه دننه راوست. کله چې د هغې پلار هغه ولیده، نو د هغه په لیدلو خوشحاله شو او هرکلی یې ورته ووایه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_3.mp3', '', 1761754199, 1761754199),
(43018, 'Judges 19:4', 'Judges', 19, 4, 'د هغه خسر ټینګار وکړ چې هغه پاتې شي، نو هغه هلته درې ورځې پاتې شو. هغوی هلته خپله ډوډۍ خوړله او شپې یې تېرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_4.mp3', '', 1761754199, 1761754199),
(43019, 'Judges 19:5', 'Judges', 19, 5, 'د څلورمې ورځې په سهار هغوی وختي پاڅېدل او تګ ته تیار شول. خو خسر خپل زوم ته وویل: «لومړی یو څه وخورئ چې د سفر دپاره تکړه شئ او وروسته به بیا لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_5.mp3', '', 1761754199, 1761754199),
(43020, 'Judges 19:6', 'Judges', 19, 6, 'نو هغوی دواړه سره کښېناستل او ویې خوړل او ویې څښل. بیا خسر یې ورته وویل: «مهرباني وکړئ نن شپه هم زمونږ سره پاتې شئ او په خوشحالۍ سره یې تېره کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_6.mp3', '', 1761754199, 1761754199),
(43021, 'Judges 19:7', 'Judges', 19, 7, 'لاوي کوښښ کاوه چې لاړ شي، خو خسر یې ورڅخه په کلکه وغوښتل چې پاتې شي، نو هغه بله شپه هم هلته پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_7.mp3', '', 1761754199, 1761754199),
(43022, 'Judges 19:8', 'Judges', 19, 8, 'د پنځمې ورځې په سهار هغه وختي پاڅېده چې لاړ شي، خو د ښځې پلار وویل: «یو څه وخورئ، بیا کولای شئ چې ماسپښین لاړ شئ.» نو هغو دواړو یوځای ډوډۍ وخوړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_8.mp3', '', 1761754199, 1761754199),
(43023, 'Judges 19:9', 'Judges', 19, 9, 'کله چې هغه سړی او د هغه وینځه او نوکر پاڅېدل چې لاړ شي، د هغه خسر وویل: «ګورئ، اوس ورځ تېره شوې ده او ماښام نژدې دی. یوه بله شپه هم زمونږ سره پاتې شئ او خوشحاله اوسئ. بیا کولای شئ چې سهار وختي پاڅېږئ او خپل کور ته لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_9.mp3', '', 1761754199, 1761754199),
(43024, 'Judges 19:12', 'Judges', 19, 12, 'خو بادار یې وویل: «نه، مونږ په دې پردي ښار کې چې اسراییلیان په کې نشته نه پاتې کېږو. مونږ به جبعې ته لاړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_12.mp3', '', 1761754199, 1761754199),
(43025, 'Judges 19:13', 'Judges', 19, 13, 'راځئ کوښښ وکړو چې جبعې یا رامه ته ځانونه ورسوو او د دې دواړو ځایونو څخه په یو ځای کې شپه تېره کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_13.mp3', '', 1761754199, 1761754199),
(43026, 'Judges 19:14', 'Judges', 19, 14, 'نو هغوی روان شول او د لمر پرېواته په وخت جبعې ته چې د بنیامین په سیمه کې وه، ورسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_14.mp3', '', 1761754199, 1761754199),
(43027, 'Judges 19:15', 'Judges', 19, 15, 'هغوی د لارې څخه راوګرځېدل چې په هغه ځای کې شپه تېره کړي. خو هېچا نه غوښتل چې هغوی د ځان سره د شپې تېرولو دپاره بوځي. نو هغوی لاړل او د ښار په چوک کې کښېناستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_15.mp3', '', 1761754199, 1761754199),
(43028, 'Judges 19:16', 'Judges', 19, 16, 'په همدې وخت کې یو زوړ سړی چې ټوله ورځ یې په پټي کې کار کړی ؤ او کور ته روان ؤ راغی. په جبعه کې چې کوم خلک اوسېدل، هغوی زیاتره د بنیامین د قبیلې څخه وو، خو دا سړی په اصل کې د افرایم د غرنۍ سیمې څخه ؤ، خو په جبعه کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_16.mp3', '', 1761754199, 1761754199),
(43029, 'Judges 19:17', 'Judges', 19, 17, 'هغه سړي هغه مسافر د ښارګوټي په چوک کې ولیده او پوښتنه یې ترې وکړه: «د کوم ځای څخه راغلي یئ او چېرته روان یئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_17.mp3', '', 1761754199, 1761754199),
(43030, 'Judges 19:18', 'Judges', 19, 18, 'لاوي په ځواب کې وویل: «مونږ د یهودا د بیت لحم څخه راغلي یو او د افرایم د غرنۍ سیمې یو لېرې ځای ته چې مونږ په کې اوسېږو، روان یو. خو هېڅوک نه غواړي مونږ خپل کور ته بوځي چې شپه ورسره تېره وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_18.mp3', '', 1761754199, 1761754199),
(43031, 'Judges 19:19', 'Judges', 19, 19, 'مونږ د خپلو خرو دپاره بوس او پروړه او د خپل ځان او خپلې ښځې او خپل نوکر دپاره ډوډۍ او شراب راوړي دي. مونږ بل هېڅ شي ته اړتیا نه لرو پرته له یو ځای څخه چې په کې ویده شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_19.mp3', '', 1761754199, 1761754199),
(43032, 'Judges 19:20', 'Judges', 19, 20, 'هغه زوړ سړي وویل: «زه خپل کور ته ستاسو د راتللو هرکلی کوم چې شپه راسره وکړئ او زما مېلمانه شئ. خو په چوک کې شپه مه کوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_20.mp3', '', 1761754199, 1761754199),
(43033, 'Judges 19:21', 'Judges', 19, 21, 'نو هغه زوړ سړي هغوی خپل کور ته بوتلل او د هغوی خره یې ماړه کړل. بیا هغوی خپلې پښې ووینځلې او ډوډۍ یې وخوړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_21.mp3', '', 1761754199, 1761754199),
(43034, 'Judges 19:22', 'Judges', 19, 22, 'په داسې حال کې چې هغوی خپل زړونه خوشحالول، د ښارګوټي ځینې بدکاره خلک د کور څخه راچاپېر شول. هغوی دروازه په زور ووهله او د کور خاوند یعنې زوړ سړي ته یې غږ وکړ: «ستا کور ته چې کوم سړی راغلی دی هغه مونږ ته راوباسه چې بد کار ورسره وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_22.mp3', '', 1761754199, 1761754199),
(43035, 'Judges 19:23', 'Judges', 19, 23, 'خو د کور خاوند دباندې ووت او هغوی ته یې وویل: «نه، زما دوستانو! داسې خراب او بد اخلاقه کار مه کوئ! دا سړی زما مېلمه دی، داسې شرموونکی کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_23.mp3', '', 1761754199, 1761754199),
(43036, 'Judges 19:24', 'Judges', 19, 24, 'ګورئ، زه به تاسو ته خپله پېغله لور او زما د مېلمه وینځه راولم، هرڅه چې غواړئ د هغوی سره یې وکړئ، خو د دې سړي سره داسې شرمناکه کار مه کوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_24.mp3', '', 1761754199, 1761754199),
(43037, 'Judges 19:25', 'Judges', 19, 25, 'خو هغو خلکو د هغه خبرو ته غوږ ونه نیوه. نو هغه لاوي خپله وینځه ونیوله او هغوی ته یې دباندې ورولېږله. هغوی هغه بې عزته کړه او ټوله شپه یې ورباندې تېری وکړ او سهار یې پرېښودله چې لاړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_25.mp3', '', 1761754199, 1761754199),
(43038, 'Judges 19:26', 'Judges', 19, 26, 'سهار وختي هغه ښځه بېرته راغله او د هغه کور په دروازه کې چې د هغې مېړه په کې مېلمه ؤ، ولوېدله او د سهار تر رڼا کېدلو پورې هلته پرته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_26.mp3', '', 1761754199, 1761754199),
(43039, 'Judges 19:27', 'Judges', 19, 27, 'سهار د هغې مېړه پاڅېده او کله چې هغه دروازه خلاصه کړه چې په خپله لاره لاړ شي، نو ویې لیدل چې وینځه یې د دروازې په خوله کې پرته وه او لاسونه یې د دروازې په خوله کې ایښي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_27.mp3', '', 1761754199, 1761754199),
(43040, 'Judges 19:28', 'Judges', 19, 28, 'هغه خپلې وینځې ته وویل: «پاڅېږه چې لاړ شو.» خو هېڅ ځواب یې وانه ورېد. بیا هغه سړي د هغې مړی په خپل خره باندې کېښود او کور ته روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_28.mp3', '', 1761754199, 1761754199),
(43041, 'Judges 19:29', 'Judges', 19, 29, 'کله چې کور ته ورسېده، نو یو چاقو یې راواخیست او د خپلې وینځې مړی یې دولس ټوټې کړ او د اسراییلو دولسو قبیلو ته یې یوه یوه ټوټه ورولېږله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_29.mp3', '', 1761754199, 1761754199),
(43042, 'Judges 19:30', 'Judges', 19, 30, 'هرچا چې هغه لیدله نو ویل یې: «د کومې ورځې نه چې اسراییلیان د مصر څخه راوتلي دي داسې کار هېڅکله نه لیدل شوی او نه شوی دی. مونږ باید په دې هکله فکر وکړو او خبرې وکړو چې څه باید وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges19_verse_30.mp3', '', 1761754199, 1761754199),
(43043, 'Amos 3:1', 'Amos', 3, 1, 'ای د اسراییلو خلکو، دې خبرو ته چې څښتن په کې ستاسو یعنې د ټول قوم په خلاف چې د مصر څخه یې راوویستلئ، غوږ ونیسئ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_1.mp3', '', 1761754199, 1761754199),
(43044, 'Amos 3:2', 'Amos', 3, 2, '«د ځمکې په مخ ټولو قومونو کې تاسې یوازېنی قوم یئ چې ما غوره کړي یئ، نو ستاسو د ډېرو ګناهونو په خاطر باید جزا درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_2.mp3', '', 1761754199, 1761754199),
(43045, 'Amos 3:3', 'Amos', 3, 3, 'ایا دوه کسان سفر کولی شي یوځای بې له دې چې موافق وي چې داسې وکړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_3.mp3', '', 1761754199, 1761754199),
(43046, 'Amos 3:4', 'Amos', 3, 4, 'ایا کوم زمری غړمبیږي په ځنګل کې چې ترڅو یې ښکار نه وي لیدلی؟ ایا د زمري بچي غوریږي په خپل غار کې ترڅو یې چې کوم شی نه وي نیولی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_4.mp3', '', 1761754199, 1761754199),
(43047, 'Amos 3:5', 'Amos', 3, 5, 'ایا په تیلک کې راګېریږي مرغۍ که چېرې نه وي ایښی په کې د خوراک کوم شی؟ ایا بېرته راټولیږي یو دام؟ که چېرې په کې نه وي نیول شوی کوم شی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_5.mp3', '', 1761754199, 1761754199),
(43048, 'Amos 3:6', 'Amos', 3, 6, 'کله چې ووهل شي د جنګ سرنی ایا خلک نه وېریږي؟ ایا په ښار باندې راتلی شي مصیبت ترڅو نه وي نازل کړی څښتن یو افت؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_6.mp3', '', 1761754199, 1761754199),
(43049, 'Amos 3:7', 'Amos', 3, 7, 'څښتن تعالی هېڅکله کوم کار نه کوي ترڅو خپلو خادمانو یعنې پیغمبرانو ته یې خپل پلان ښودلی نه وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_7.mp3', '', 1761754199, 1761754199),
(43050, 'Amos 3:8', 'Amos', 3, 8, 'چې یو زمری کله غړمبیږي نو داسې به وي کوم څوک چې ونه وېریږي؟ کله چې کړي څښتن تعالی خبرې نو څوک کولی شي چې اعلان نه کړي پیغام د هغه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_8.mp3', '', 1761754199, 1761754199),
(43051, 'Amos 3:9', 'Amos', 3, 9, 'د اشدود د کلاګانو خلکو ته او د مصر د کلاګانو خلکو ته اعلان وکړئ: «د سامرې په شاوخوا غونډیو باندې سره راټول شئ. او هلته یوه لویه ګډوډي او هغه ظلمونه چې په هغه ځای کې کیږي، وګورئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_9.mp3', '', 1761754199, 1761754199),
(43052, 'Amos 3:10', 'Amos', 3, 10, 'څښتن وایي: «د سامرې خلک په دې نه پوهیږي چې څنګه سم کار وکړي. خلکو خپلې کلاګانې د هغو شیانو څخه ډکې کړې دي چې په غلا او ظلم زیاتي باندې یې لاسته راوړي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_10.mp3', '', 1761754199, 1761754199),
(43053, 'Amos 3:11', 'Amos', 3, 11, 'نو څښتن تعالی داسې وایي: «دښمن به د هغوی وطن کلابند کړي او د هغوی دفاعي قدرت به له منځه یوسي او د هغوی کلاګانې به لوټ کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_11.mp3', '', 1761754199, 1761754199),
(43054, 'Amos 3:12', 'Amos', 3, 12, 'څښتن داسې وایي: «لکه څنګه چې یو شپون د زمري د خولې نه د پسه یوازې دوه پښې او د غوږ یوه ټوټه به بېرته لاسته راوړي، نو د سامرې د خلکو نه به چې اوس د عیاشۍ په کټونو او کوچونو باندې پراته دي، یوازې څو تنه ژوندي پاتې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_12.mp3', '', 1761754199, 1761754199),
(43055, 'Amos 3:13', 'Amos', 3, 13, 'مطلق قادر څښتن خدای وایي: «اوس غوږ ونیسئ او د یعقوب اولادې ته خبرداری ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_13.mp3', '', 1761754199, 1761754199),
(43056, 'Amos 3:14', 'Amos', 3, 14, 'په کومه ورځ چې زه د اسراییلو خلکو ته د هغوی د ګناهونو په سبب سزا ورکوم، نو زه به د بیت‌ییل د قربانۍ ځایونه وران کړم. د قربانۍ د ځای ښکرونه به ټوټې ټوټې شي او په ځمکه به راوغورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_14.mp3', '', 1761754199, 1761754199),
(43057, 'Amos 3:15', 'Amos', 3, 15, 'زه به د اوړي او ژمي تېرولو کورونه وران کړم. هغه کورونه چې د فیل په غاښونو باندې ښکلي کړای شوي دي، هغه به په کنډوالو باندې بدل شي او هر لوی کور به وران شي.» دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos3_verse_15.mp3', '', 1761754199, 1761754199),
(43058, 'Psalms 91:1', 'Psalms', 91, 1, 'څوک چې اوسیږي په پناه د خدای تعالی کې هغه به ژوند تېر کړي د خدای مطلق قادر د سیوري لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_1.mp3', '', 1761754199, 1761754199),
(43059, 'Psalms 91:2', 'Psalms', 91, 2, 'زه به څښتن ته داسې ووایم چې ته پناه ځای او هم کلا یې زما او زما خدای چې توکل پرې کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_2.mp3', '', 1761754199, 1761754199),
(43060, 'Psalms 91:3', 'Psalms', 91, 3, 'په رښتیا به څښتن خلاص کړي تاسو د ښکاریانو د دامونو څخه او د وژونکو ناروغیو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_3.mp3', '', 1761754199, 1761754199),
(43061, 'Psalms 91:4', 'Psalms', 91, 4, 'خپلو وزرونو باندې تاسو به کړي پټ هغه تاسو به ومومئ پناه هلته د خدای وفا به لکه سپر او دېوال ستاسو ساتنه وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_4.mp3', '', 1761754199, 1761754199),
(43062, 'Psalms 91:5', 'Psalms', 91, 5, 'د شپې به نه وېرېږئ تاسې له هېڅ خطره یا د هغه غشي چې ویشتل کیږي به د ورځې له خوا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_5.mp3', '', 1761754199, 1761754199),
(43063, 'Psalms 91:6', 'Psalms', 91, 6, 'یا هغې وبا نه چې خپریږي به تیاره کې نه هغې بلا نه چې وژل کوي غرمه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_6.mp3', '', 1761754199, 1761754199),
(43064, 'Psalms 91:7', 'Psalms', 91, 7, 'که دې په خوا کې زر کسان مړه شي او د ښي لاس سره دې لس زره نو بیا به هم تاته ونه رسي زیان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_7.mp3', '', 1761754199, 1761754199),
