(43066, 'Psalms 91:9', 'Psalms', 91, 9, 'دا چې څښتن دې پناه ځای کړ خپل او خدای تعالی دې کړلو خپله کلا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_9.mp3', '', 1761754199, 1761754199),
(43067, 'Psalms 91:10', 'Psalms', 91, 10, 'نو هېڅ بدي به په تا رانه شي ستا کور ته درنژدې به هېڅ کومه بلا رانه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_10.mp3', '', 1761754199, 1761754199),
(43068, 'Psalms 91:11', 'Psalms', 91, 11, 'ځکه چې خدای به فرښتو خپلو ته حکم وکړي چې چېرته ځې ته نو هغوی به ستا ساتنه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_11.mp3', '', 1761754199, 1761754199),
(43069, 'Psalms 91:12', 'Psalms', 91, 12, 'خپلو لاسونو کې به پورته کړي تا چې پښه دې ونه لګي تیږه باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_12.mp3', '', 1761754199, 1761754199),
(43070, 'Psalms 91:13', 'Psalms', 91, 13, 'ته به زمریان او چمچه ماران تر‌پښو لاندې کړې هم داړونکي زمریان او زهرجن ماران به تر‌پښو لاندې کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_13.mp3', '', 1761754199, 1761754199),
(43071, 'Psalms 91:14', 'Psalms', 91, 14, 'خدای وایي: «خلاصون به ورکړم هغه چاته چې زما سره کړي مینه وبه ساتم هغه څوک چې باور ولري په ما باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_14.mp3', '', 1761754199, 1761754199),
(43072, 'Psalms 91:15', 'Psalms', 91, 15, 'کله چې ماته د زارۍ لاسونه پورته کړي نو قبلوم یې دعا زه به ملګری یم هغه سره په سخته کې هم به یې ژغورم او هم ورکوم به عزت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms91_verse_15.mp3', '', 1761754199, 1761754199),
