(43094, 'Joshua 7:4', 'Joshua', 7, 4, 'نو نژدې درې زره اسراییلیانو په هغوی باندې حمله وکړه، خو په شا تګ ته مجبور شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_4.mp3', '', 1761754199, 1761754199),
(43095, 'Joshua 7:5', 'Joshua', 7, 5, 'د عای جنګیالیو هغوی د ښار د دروازې څخه د تیږو تر کانونو پورې تعقیب کړل او د غونډۍ څخه د ښکته کېدلو په وخت کې یې د هغوی څخه نژدې شپږ دېرش تنه ووژل. بیا اسراییلیانو خپل جرات له لاسه ورکړ او ووېرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_5.mp3', '', 1761754199, 1761754199),
(43096, 'Joshua 7:6', 'Joshua', 7, 6, 'یوشع او د اسراییلو مشرانو د ډېره غمه خپل کالي وشکول، په خپلو سرونو باندې یې خاورې باد کړې او تر لمرپرېواته پورې د څښتن د لوظ د صندوق په مخکې په ځمکه باندې پړمخې پرېوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_6.mp3', '', 1761754199, 1761754199),
(43097, 'Joshua 7:7', 'Joshua', 7, 7, 'یوشع وویل: «ای څښتن تعالی! تا ولې د اردن د سیند څخه راپورې ویستلو؟ د دې دپاره چې مونږ اموریانو ته په لاس ورکړې چې له منځه مو یوسي؟ ولې مونږ د اردن د سیند په بله غاړه باندې پاتې نه شو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_7.mp3', '', 1761754199, 1761754199),
(43098, 'Joshua 7:8', 'Joshua', 7, 8, 'ای څښتنه، اوس چې اسراییلیان د دښمن څخه په شا شوي دي، زه نه پوهېږم چې څه ووایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_8.mp3', '', 1761754199, 1761754199),
(43099, 'Joshua 7:9', 'Joshua', 7, 9, 'کنعانیان او د هېواد نور خلک به د دې څخه خبر شي. هغوی به مونږ کلابند کړي او زمونږ نوم به د ځمکې د مخ څخه ورک کړي! بیا به ته د خپل عزت د ساتلو دپاره څه وکړې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_9.mp3', '', 1761754199, 1761754199),
(43100, 'Joshua 7:10', 'Joshua', 7, 10, 'څښتن یوشع ته وویل: «پاڅېږه! ولې داسې پړمخې پروت یې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_10.mp3', '', 1761754199, 1761754199),
(43101, 'Joshua 7:11', 'Joshua', 7, 11, 'د اسراییلو خلکو ګناه کړې ده! هغوی زما هغه تړون مات کړی دی چې ما په هغوی باندې حکم کړی ؤ چې عمل ورباندې وکړي. هغوی د هغو شیانو څخه چې باید له منځه وړل شوي وای ځینې شیان وړي دي. هغه یې غلا کړل، د خپلو شیانو سره یې کېښودل او د هغو په هکله یې دروغ وویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_11.mp3', '', 1761754199, 1761754199),
(43102, 'Joshua 7:12', 'Joshua', 7, 12, 'له همدې امله اسراییلیان د خپلو دښمنانو په وړاندې نه شي ودرېدلی. هغوی ځکه د خپلو دښمنانو څخه په شا کیږي او تښتي چې هغوی خپله په تباهۍ باندې محکوم شوي دي! زه به تر هغې پورې نور د هغوی سره نه اوسم، ترڅو هغه شیان له منځه یونسي چې د هغو د له منځه وړلو حکم ورباندې شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_12.mp3', '', 1761754199, 1761754199),
(43103, 'Joshua 7:13', 'Joshua', 7, 13, 'لاړ شه، خپل قوم پاک کړه او هغوی تیار کړه چې زما حضور ته راشي. هغوی ته ووایه چې سبا تیار شي، ځکه چې زه د اسراییلو څښتن خدای داسې وایم: ‹ای د اسراییلو خلکو، ستاسو سره یو څه شیان شته چې ما د هغو د له منځه وړلو حکم درباندې کړی دی! تاسو تر هغه وخته پورې د خپلو دښمنانو په وړاندې نه شئ ودرېدلی، ترڅو دا شیان د ځان نه لېرې نه کړئ!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_13.mp3', '', 1761754199, 1761754199),
(43104, 'Joshua 7:14', 'Joshua', 7, 14, 'سبا سهار ټول سره راټول شئ. تاسو به قبیله په قبیله رامخکې شئ او څښتن به وښایي چې کومه قبیله ګناهکاره ده. بیا به د هماغې قبیلې طایفې مخکې راشي او څښتن به وښایي چې کومه طایفه ګناهکاره ده. بیا دې د هماغې طایفې کورنۍ راشي او څښتن به ګناهکاره کورنۍ په ګوته کړي. په اخره کې دې د هماغې کورنۍ کسان راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_14.mp3', '', 1761754199, 1761754199),
(43105, 'Joshua 7:15', 'Joshua', 7, 15, 'د چا سره چې هغه شیان پیدا شي چې باید له منځه وړل شوي وای، نو هغه کس باید د خپلې کورنۍ سره ووژل شي، د هغوی مړي دې وسوځول شي او مال او جایداد یې په اور کې وغورځول شي، ځکه چې هغه زما تړون مات کړی دی او اسراییلیان یې سخت شرمولي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_15.mp3', '', 1761754199, 1761754199),
(43106, 'Joshua 7:16', 'Joshua', 7, 16, 'یوشع سهار وختي پاڅېده او هره قبیله یې د څښتن حضور ته راوستله، چېرته چې څښتن وښودله چې د یهودا قبیله ګناهکاره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_16.mp3', '', 1761754199, 1761754199),
(43107, 'Joshua 7:17', 'Joshua', 7, 17, 'بیا یوشع د یهودا طایفې راوستلې او څښتن وښودله چې د زارح طایفه ګناهکاره وه. هغه د زارح د طایفې یوه یوه کورنۍ راوستله او څښتن وښودله چې د زبدي کورنۍ ګناهکاره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_17.mp3', '', 1761754199, 1761754199),
(43108, 'Joshua 7:18', 'Joshua', 7, 18, 'په اخره کې یوشع د زبدي د کورنۍ یو یو کس رامخته کړ او څښتن وښودل چې عخان ګناهکار ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_18.mp3', '', 1761754199, 1761754199),
(43109, 'Joshua 7:19', 'Joshua', 7, 19, 'یوشع عخان ته وویل: «زما زویه، د اسراییلو د څښتن خدای په مخکې رښتیا ووایه او اقرار وکړه. اوس ماته ووایه چې تا څه کړي دي. زما څخه د دې خبرې د پټولو هڅه مه کوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_19.mp3', '', 1761754199, 1761754199),
(43110, 'Joshua 7:20', 'Joshua', 7, 20, 'عخان په ځواب کې وویل: «دا رښتیا دي! ما د اسراییلو د څښتن خدای په وړاندې ګناه کړې ده او دا هغه څه دي چې ما کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua7_verse_20.mp3', '', 1761754199, 1761754199);